// src/components/Header.js
import React, { useEffect, useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import '../styles/Header.css';

const API_BASE_URL = (process.env.REACT_APP_API_URL || '').trim().replace(/\/+$/, '');

function Header() {
  const location = useLocation();  // Get the current route path
  const [apiStatus, setApiStatus] = useState('checking'); // 'checking' | 'live' | 'offline'

  // Ping the backend once on load so the nav reflects whether the pricing
  // engine is actually reachable, not just whether the page rendered.
  useEffect(() => {
    if (!API_BASE_URL) {
      setApiStatus('offline');
      return;
    }
    let cancelled = false;
    fetch(`${API_BASE_URL}/health`)
      .then((res) => {
        if (!cancelled) setApiStatus(res.ok ? 'live' : 'offline');
      })
      .catch(() => {
        if (!cancelled) setApiStatus('offline');
      });
    return () => {
      cancelled = true;
    };
  }, []);

  return (
    <div className="header">
      <div className="header-left">
        <Link to="/">
          <button className={`header-btn home-btn ${location.pathname === '/' ? 'active' : ''}`}>Home</button>
        </Link>
        <Link to="/modeling">
          <button className={`header-btn model-btn ${location.pathname === '/modeling' ? 'active' : ''}`}>Options Pricing</button>
        </Link>
        <Link to="/history">
          <button className={`header-btn history-btn ${location.pathname === '/history' ? 'active' : ''}`}>History</button>
        </Link>
        <Link to="/documentation">
          <button className={`header-btn doc-btn ${location.pathname === '/documentation' ? 'active' : ''}`}>Documentations</button>
        </Link>
      </div>
      <div className="header-right">
        <div className="api-status" title={`API ${apiStatus}`}>
          <span className={`status-dot status-dot--${apiStatus}`} />
          <span className="status-label">{apiStatus === 'checking' ? 'checking…' : apiStatus}</span>
        </div>
      </div>
      <div className="social-links">
        {/* LinkedIn Link */}
        <a href="https://www.linkedin.com/in/yanisaks/" id="linkedin" className="social-btn flex-center" target="_blank" rel="noopener noreferrer">
          <svg viewBox="0 0 24 24" height="24" width="24" xmlns="http://www.w3.org/2000/svg"><path d="M4.98 3.5c0 1.381-1.11 2.5-2.48 2.5s-2.48-1.119-2.48-2.5c0-1.38 1.11-2.5 2.48-2.5s2.48 1.12 2.48 2.5zm.02 4.5h-5v16h5v-16zm7.982 0h-4.968v16h4.969v-8.399c0-4.67 6.029-5.052 6.029 0v8.399h4.988v-10.131c0-7.88-8.922-7.593-11.018-3.714v-2.155z"></path></svg>
          <span>LinkedIn</span>
        </a>

        {/* GitHub Link */}
        <a href="https://github.com/yaaks7" id="github" className="social-btn flex-center" target="_blank" rel="noopener noreferrer">
          <svg viewBox="0 0 24 24" height="24" width="24" xmlns="http://www.w3.org/2000/svg"><path d="M12 0c-6.626 0-12 5.373-12 12 0 5.302 3.438 9.8 8.207 11.387.599.111.793-.261.793-.577v-2.234c-3.338.726-4.033-1.416-4.033-1.416-.546-1.387-1.333-1.756-1.333-1.756-1.089-.745.083-.729.083-.729 1.205.084 1.839 1.237 1.839 1.237 1.07 1.834 2.807 1.304 3.492.997.107-.775.418-1.305.762-1.604-2.665-.305-5.467-1.334-5.467-5.931 0-1.311.469-2.381 1.236-3.221-.124-.303-.535-1.524.117-3.176 0 0 1.008-.322 3.301 1.23.957-.266 1.983-.399 3.003-.404 1.02.005 2.047.138 3.006.404 2.291-1.552 3.297-1.23 3.297-1.23.653 1.653.242 2.874.118 3.176.77.84 1.235 1.911 1.235 3.221 0 4.609-2.807 5.624-5.479 5.921.43.372.823 1.102.823 2.222v3.293c0 .319.192.694.801.576 4.765-1.589 8.199-6.086 8.199-11.386 0-6.627-5.373-12-12-12z"></path></svg>
          <span>GitHub</span>
        </a>
      </div>
    </div>
  );
}

export default Header;
